                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == color and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            y0, x0 = min(y for y, x in cells), min(x for y, x in cells)
            shape = [(y-y0, x-x0) for y, x in cells]
            groups.setdefault(color, []).append((min(x for y, x in cells), len(cells), shape))

    # Side-by-side color lanes follow the left-to-right order in the input.
    lane_order = sorted(groups, key=lambda color: min(item[0] for item in groups[color]))
    offsets, x = {}, 0
    for color in lane_order:
        offsets[color] = x
        width = max(max(dx for dy, dx in shape) for _, _, shape in groups[color]) + 1
        x += width + 1

    out = [[0] * w for _ in range(h)]
    for color in lane_order:
        components = sorted(groups[color], key=lambda item: item[1])
        # Smaller object above larger object; each rests on the bottom with a one-row gap.
